import { createProject } from '../test-utils'

describe('Supported syntax tests', () => {
    test('DEF0715463: Support named exports and export specifiers syntax for fluent files', async () => {
        const project = createProject()

        const subrole1Id = project.registerCoalesceId('sys_user_role', { name: 'x_test.subrole1' })
        const subrole2Id = project.registerCoalesceId('sys_user_role', { name: 'x_test.subrole2' })
        const mainRoleId = project.registerCoalesceId('sys_user_role', { name: 'x_test.mainrole' })
        const m2mId = project.registerCoalesceId('sys_user_role_contains', { role: mainRoleId, contains: subrole1Id })
        const m2mId2 = project.registerCoalesceId('sys_user_role_contains', { role: mainRoleId, contains: subrole2Id })

        project.addFile({
            path: 'subrole1.now.ts',
            content: `
            import { Role } from '@servicenow/sdk/core'
            
            const role = Role({
                name: 'x_test.subrole1',
                description: 'dummy role1',
            })
            
            export { role }
            `,
        })

        project.addFile({
            path: 'subrole2.now.ts',
            content: `
            import { Role } from '@servicenow/sdk/core'
            
            const role = Role({
                name: 'x_test.subrole2',
                description: 'dummy role2',
            })
            
            export { role as subrole2 } //export with aliases 
            `,
        })

        project.addFile({
            path: 'reexporter.now.ts',
            content: `
            export { role } from './subrole1.now';
            export { subrole2 } from './subrole2.now';
            `,
        })

        project.addFile({
            path: 'mainrole.now.ts',
            content: `
            import { Role } from '@servicenow/sdk/core'
            import { role, subrole2 } from './reexporter.now';
            
            Role({
                name: 'x_test.mainrole',
                description: 'Main role description.',
                containsRoles: [role, subrole2],
            })
            `,
        })

        const output = await project.getOutput()
        expect(output).toHaveLength(8)
        const subRole1Contains = output.filter((f) => f.path.endsWith(`sys_user_role_contains_${m2mId}.xml`))
        const subRole2Contains = output.filter((f) => f.path.endsWith(`sys_user_role_contains_${m2mId2}.xml`))
        expect(subRole1Contains[0].content).toContain(`<?xml version="1.0"?>
<record_update table="sys_user_role_contains">
  <sys_user_role_contains action="INSERT_OR_UPDATE">
    <sys_id>${m2mId}</sys_id>
    <sys_scope display_value="x_test">11111111111111111111111111111111</sys_scope>
    <sys_update_name>sys_user_role_contains_${m2mId}</sys_update_name>
    <contains name="x_test.subrole1">${subrole1Id}</contains>
    <role name="x_test.mainrole">${mainRoleId}</role>
  </sys_user_role_contains>
</record_update>`)
        expect(subRole2Contains[0].content).toContain(`<?xml version="1.0"?>
<record_update table="sys_user_role_contains">
  <sys_user_role_contains action="INSERT_OR_UPDATE">
    <sys_id>${m2mId2}</sys_id>
    <sys_scope display_value="x_test">11111111111111111111111111111111</sys_scope>
    <sys_update_name>sys_user_role_contains_${m2mId2}</sys_update_name>
    <contains name="x_test.subrole2">${subrole2Id}</contains>
    <role name="x_test.mainrole">${mainRoleId}</role>
  </sys_user_role_contains>
</record_update>`)
    })
})
